@startuml

class AlphaInsurance {}

class Customer {
  + name : string
}

class Broker {
  + brokerId : string
}

class Contract {
  + contractId : string
  + billingFrequency : string
}

class InsuranceProduct {
  + price : float
}

class Offer {
  + offerId : string
  + status : string
}

class ClaimCase {
  + caseId : string
  + status : string
}

class EstimatorReport {
  + reportDate : date
  + content : string
}

class CompensationDecision {
  + eligibleCosts : float
  + totalCompensation : float
}

class Account {
  + accountNumber : string
}

AlphaInsurance "1" -- "*" Customer
Broker "1" -- "*" Customer : manages
Customer "1" -- "*" Contract
Contract "*" -- "1" InsuranceProduct
Offer "1" -- "1" Customer
Offer "1" -- "1" InsuranceProduct
Contract "1" -- "1" Offer : signedFrom
Customer "1" -- "*" ClaimCase : sends
ClaimCase "1" -- "*" EstimatorReport
EstimatorReport "*" -- "1" Estimator
ClaimCase "1" -- "0..1" CompensationDecision
CompensationDecision "1" -- "1" Customer : paidTo
Customer "1" -- "1" Account

class Estimator {}

@enduml

